begin;
create extension if not exists pgcrypto;
create table if not exists public.angelcare_marketplace_crm_leads(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('LEAD-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),lead_type text not null check(lead_type in('family','establishment','hotel','clinic','corporate','partner','supplier')),name text not null,organization_name text,email text,phone text,source text not null default 'marketplace',source_reference text,status text not null default 'new' check(status in('new','contacted','qualified','disqualified','converted','nurture','archived')),territory_id uuid,owner_id uuid,next_action text,next_action_at timestamptz,consent_evidence jsonb not null default '{}',created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_crm_accounts(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('ACC-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),account_type text not null,legal_name text not null,display_name text not null,registration_number text,territory_id uuid,status text not null default 'prospect' check(status in('prospect','qualified','client','partner','inactive','archived')),owner_id uuid,health_status text not null default 'unknown' check(health_status in('healthy','attention','at_risk','critical','unknown')),address jsonb not null default '{}',metadata jsonb not null default '{}',created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_crm_contacts(id uuid primary key default gen_random_uuid(),account_id uuid not null references public.angelcare_marketplace_crm_accounts(id) on delete cascade,full_name text not null,title text,email text,phone text,decision_role text,preferred_channel text,consent_status text not null default 'unknown',status text not null default 'active' check(status in('active','inactive','archived')),created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_crm_opportunities(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('OPP-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),account_id uuid references public.angelcare_marketplace_crm_accounts(id),lead_id uuid references public.angelcare_marketplace_crm_leads(id),name text not null,stage text not null default 'new' check(stage in('new','discovery','qualified','solution','proposal','negotiation','verbal_commitment','won','lost','on_hold')),estimated_value numeric(16,2),currency_label text not null default 'Dh',probability int not null default 5 check(probability between 0 and 100),expected_close_at date,owner_id uuid,territory_id uuid,next_action text,next_action_at timestamptz,blocker_reason text,loss_reason text,won_at timestamptz,lost_at timestamptz,created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_crm_quotes(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('QUO-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),opportunity_id uuid not null references public.angelcare_marketplace_crm_opportunities(id) on delete cascade,quote_status text not null default 'draft' check(quote_status in('draft','internal_review','submitted','negotiation','accepted','rejected','expired','cancelled')),currency_label text not null default 'Dh',subtotal numeric(16,2) not null default 0,discount_total numeric(16,2) not null default 0,tax_total numeric(16,2) not null default 0,grand_total numeric(16,2) not null default 0,valid_until date,approval_status text not null default 'not_requested' check(approval_status in('not_requested','pending','approved','rejected')),version int not null default 1,terms text,approved_by uuid,approved_at timestamptz,created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(opportunity_id,version));
create table if not exists public.angelcare_marketplace_crm_quote_lines(id uuid primary key default gen_random_uuid(),quote_id uuid not null references public.angelcare_marketplace_crm_quotes(id) on delete cascade,catalog_item_id uuid references public.angelcare_marketplace_catalog_items(id),description text not null,quantity numeric(12,2) not null default 1,unit_price numeric(16,2) not null default 0,discount_amount numeric(16,2) not null default 0,line_total numeric(16,2) not null default 0,configuration jsonb not null default '{}',sort_order int not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_crm_tasks(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('TASK-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),title text not null,description text,related_type text,related_id uuid,status text not null default 'open' check(status in('open','in_progress','blocked','completed','cancelled')),priority text not null default 'normal' check(priority in('low','normal','high','critical')),owner_id uuid,assignee_id uuid,due_at timestamptz,completed_at timestamptz,next_action text,created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_crm_communication_logs(id uuid primary key default gen_random_uuid(),related_type text not null,related_id uuid not null,channel text not null check(channel in('email','phone','whatsapp','meeting','visit','other')),direction text not null check(direction in('inbound','outbound','internal')),subject text,summary text not null,evidence_reference text,occurred_at timestamptz not null default now(),actor_id uuid,created_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_crm_proof_packs(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('PROOF-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),opportunity_id uuid not null references public.angelcare_marketplace_crm_opportunities(id) on delete cascade,status text not null default 'draft' check(status in('draft','review','approved','archived')),owner_id uuid,reviewer_id uuid,approved_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_crm_proof_pack_items(id uuid primary key default gen_random_uuid(),proof_pack_id uuid not null references public.angelcare_marketplace_crm_proof_packs(id) on delete cascade,evidence_type text not null,title text not null,evidence_url text,storage_path text,metadata jsonb not null default '{}',verified boolean not null default false,verified_by uuid,verified_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_crm_pipeline_events(id uuid primary key default gen_random_uuid(),opportunity_id uuid not null references public.angelcare_marketplace_crm_opportunities(id) on delete cascade,event_type text not null,from_stage text,to_stage text,reason text,actor_id uuid,payload jsonb not null default '{}',created_at timestamptz not null default now());
create index if not exists angelcare_crm_leads_owner_idx on public.angelcare_marketplace_crm_leads(owner_id,status,updated_at desc);create index if not exists angelcare_crm_opportunities_stage_idx on public.angelcare_marketplace_crm_opportunities(stage,owner_id,expected_close_at);create index if not exists angelcare_crm_tasks_due_idx on public.angelcare_marketplace_crm_tasks(status,due_at);
insert into public.angelcare_marketplace_permissions(permission_key,name,category,sensitive) values
('marketplace.crm.view','Voir le CRM et pipeline','CRM & Pipeline',false),('marketplace.crm.leads.manage','Gérer les leads','CRM & Pipeline',true),('marketplace.crm.accounts.manage','Gérer les comptes','CRM & Pipeline',true),('marketplace.crm.contacts.manage','Gérer les contacts','CRM & Pipeline',true),('marketplace.crm.opportunities.manage','Gérer les opportunités','CRM & Pipeline',true),('marketplace.crm.opportunities.transition','Changer le stage','CRM & Pipeline',true),('marketplace.crm.quotes.view','Voir les devis','CRM & Pipeline',false),('marketplace.crm.quotes.manage','Gérer les devis','CRM & Pipeline',true),('marketplace.crm.quotes.approve','Approuver les devis','CRM & Pipeline',true),('marketplace.crm.tasks.manage','Gérer les tâches','CRM & Pipeline',true),('marketplace.crm.communications.log','Journaliser les communications','CRM & Pipeline',true),('marketplace.crm.proof_packs.view','Voir les proof packs','CRM & Pipeline',false),('marketplace.crm.proof_packs.manage','Gérer les proof packs','CRM & Pipeline',true),('marketplace.crm.export','Exporter les preuves CRM','CRM & Pipeline',true)
on conflict(permission_key) do update set name=excluded.name,category=excluded.category,sensitive=excluded.sensitive;
insert into public.angelcare_marketplace_role_permissions(role_key,permission_key) select r.role_key,p.permission_key from public.angelcare_marketplace_roles r cross join public.angelcare_marketplace_permissions p where r.role_key in('marketplace_super_admin','marketplace_executive') and p.permission_key like 'marketplace.crm.%' on conflict do nothing;
update public.angelcare_marketplace_modules set status='enabled',enabled=true,health_status='healthy',route_prefix='/angelcare-marketplace/admin/commercial',required_permissions=array['marketplace.crm.view']::text[],version=version+1,updated_at=now() where module_key='marketplace.crm' or introduced_by_mega_zip=10;
insert into public.angelcare_marketplace_feature_flags(flag_key,name,description,enabled,status,reason) values('marketplace.crm.enabled','CRM & Partnership Pipeline','Leads, comptes, opportunités, devis, tâches, communications et preuves.',true,'active','Ultra Delivery 2/5') on conflict(flag_key) do update set enabled=true,status='active',reason=excluded.reason,updated_at=now();
alter table public.angelcare_marketplace_crm_leads enable row level security;alter table public.angelcare_marketplace_crm_accounts enable row level security;alter table public.angelcare_marketplace_crm_contacts enable row level security;alter table public.angelcare_marketplace_crm_opportunities enable row level security;alter table public.angelcare_marketplace_crm_quotes enable row level security;alter table public.angelcare_marketplace_crm_quote_lines enable row level security;alter table public.angelcare_marketplace_crm_tasks enable row level security;alter table public.angelcare_marketplace_crm_communication_logs enable row level security;alter table public.angelcare_marketplace_crm_proof_packs enable row level security;alter table public.angelcare_marketplace_crm_proof_pack_items enable row level security;alter table public.angelcare_marketplace_crm_pipeline_events enable row level security;
revoke all on table public.angelcare_marketplace_crm_leads,public.angelcare_marketplace_crm_accounts,public.angelcare_marketplace_crm_contacts,public.angelcare_marketplace_crm_opportunities,public.angelcare_marketplace_crm_quotes,public.angelcare_marketplace_crm_quote_lines,public.angelcare_marketplace_crm_tasks,public.angelcare_marketplace_crm_communication_logs,public.angelcare_marketplace_crm_proof_packs,public.angelcare_marketplace_crm_proof_pack_items,public.angelcare_marketplace_crm_pipeline_events from anon,authenticated;
grant all on table public.angelcare_marketplace_crm_leads,public.angelcare_marketplace_crm_accounts,public.angelcare_marketplace_crm_contacts,public.angelcare_marketplace_crm_opportunities,public.angelcare_marketplace_crm_quotes,public.angelcare_marketplace_crm_quote_lines,public.angelcare_marketplace_crm_tasks,public.angelcare_marketplace_crm_communication_logs,public.angelcare_marketplace_crm_proof_packs,public.angelcare_marketplace_crm_proof_pack_items,public.angelcare_marketplace_crm_pipeline_events to service_role;
commit;
